import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.Cs11k9ph.js";const g=JSON.parse('{"title":"🖥 服务器端","description":"","frontmatter":{},"headers":[],"relativePath":"server.md","filePath":"server.md","lastUpdated":1790096204000}'),i={name:"server.md"};function l(d,e,n,s,h,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="🖥-服务器端" tabindex="-1">🖥 服务器端 <a class="header-anchor" href="#🖥-服务器端" aria-label="Permalink to &quot;🖥 服务器端&quot;">​</a></h1><blockquote><p>本文档对应 <strong>AgoraIn v3.2.5</strong> 集控服务器。更多详情请参阅：</p><ul><li><a href="/deploy.html">部署指南 →</a> — 集控服务器构建、部署与配置（<code>config.json</code>）</li><li><a href="/api.html">API 文档 →</a> — 服务器 REST API 参考</li><li><a href="/features.html#集控服务器server">功能特性 →</a> — 集控服务器功能说明</li></ul></blockquote><hr><h2 id="初始化设置向导" tabindex="-1">初始化设置向导 <a class="header-anchor" href="#初始化设置向导" aria-label="Permalink to &quot;初始化设置向导&quot;">​</a></h2><p>首次部署集控服务器时，系统会自动进入<strong>设置向导</strong>流程，引导管理员完成基础配置。</p><h3 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h3><ol><li><strong>首次访问自动跳转</strong>：当服务器检测到尚未完成初始化配置时，浏览器访问任意页面将自动重定向到设置向导页面（<code>/setup</code>）</li><li><strong>填写配置信息</strong>：在向导页面中配置服务器名称、管理员密码等基本信息</li><li><strong>提交完成初始化</strong>：配置信息提交后，服务器写入 <code>config.json</code> 并创建数据库，完成初始化</li></ol><h3 id="相关接口" tabindex="-1">相关接口 <a class="header-anchor" href="#相关接口" aria-label="Permalink to &quot;相关接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /setup</code></td><td>设置向导页面（首次部署时自动跳转至此）</td></tr><tr><td><code>POST /api/setup</code></td><td>提交初始化配置，完成服务器首次设置</td></tr></tbody></table><blockquote><p>💡 初始化完成后，再次访问服务器将正常进入 Web 管理面板，不再跳转到向导页面。</p></blockquote><hr><h2 id="服务器离线激活" tabindex="-1">服务器离线激活 <a class="header-anchor" href="#服务器离线激活" aria-label="Permalink to &quot;服务器离线激活&quot;">​</a></h2><p>集控服务器支持<strong>离线激活</strong>功能，适用于无法直接联网的部署环境。通过硬件指纹绑定授权，确保服务器在无网络环境下也能完成授权验证。</p><h3 id="激活流程" tabindex="-1">激活流程 <a class="header-anchor" href="#激活流程" aria-label="Permalink to &quot;激活流程&quot;">​</a></h3><ol><li><strong>获取服务器指纹</strong>：调用 <code>GET /api/server/fingerprint</code> 接口获取当前服务器的唯一硬件指纹</li><li><strong>提交激活请求</strong>：将指纹与授权码一起提交到 <code>POST /api/server/activate</code>，完成离线激活</li><li><strong>查看授权状态</strong>：通过 <code>GET /api/server/license</code> 查询当前服务器的授权信息（授权状态、过期时间等）</li></ol><h3 id="相关接口-1" tabindex="-1">相关接口 <a class="header-anchor" href="#相关接口-1" aria-label="Permalink to &quot;相关接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /api/server/fingerprint</code></td><td>获取服务器硬件指纹（用于离线激活绑定）</td></tr><tr><td><code>POST /api/server/activate</code></td><td>提交激活码，完成服务器授权激活</td></tr><tr><td><code>GET /api/server/license</code></td><td>查询当前服务器授权状态与授权信息</td></tr></tbody></table><h3 id="典型使用场景" tabindex="-1">典型使用场景 <a class="header-anchor" href="#典型使用场景" aria-label="Permalink to &quot;典型使用场景&quot;">​</a></h3><ul><li><strong>内网部署</strong>：服务器部署在无互联网访问的内网环境中，通过离线方式完成授权</li><li><strong>安全合规</strong>：对网络访问有严格限制的机构，无需开放外网即可激活服务器</li><li><strong>迁移部署</strong>：更换服务器硬件时，可重新获取指纹并申请新的激活码</li></ul><hr><h2 id="购买授权" tabindex="-1">购买授权 <a class="header-anchor" href="#购买授权" aria-label="Permalink to &quot;购买授权&quot;">​</a></h2><p>如需购买 AgoraIn 集控服务器授权，可通过以下方式联系客服：</p><div style="margin:20px 0;padding:20px;border-radius:12px;background:linear-gradient(135deg, rgba(124,58,237,0.08), rgba(37,99,235,0.08));border:1px solid rgba(139,92,246,0.3);"><h3 id="💬-购买授权咨询" tabindex="-1">💬 购买授权咨询 <a class="header-anchor" href="#💬-购买授权咨询" aria-label="Permalink to &quot;💬 购买授权咨询&quot;">​</a></h3><p>欢迎通过<strong>微信企业客服</strong>咨询授权购买事宜，我们将为您提供专业的授权方案与技术支持。</p><p><a href="https://work.weixin.qq.com/kfid/kfc4bf6fef5cfae527d" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:8px;padding:12px 28px;margin-top:12px;border-radius:10px;font-weight:700;font-size:0.95rem;color:#fff;background:linear-gradient(135deg, #7c3aed, #4f46e5 55%, #2563eb);text-decoration:none;transition:all 0.25s;box-shadow:0 4px 16px rgba(124,58,237,0.3);">💬 联系微信企业客服</a></p></div><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/deploy.html">部署指南</a> — 服务器构建、部署与 <code>config.json</code> 配置</li><li><a href="/api.html">API 文档</a> — 完整 REST API 端点参考</li><li><a href="/features.html#集控服务器server">功能特性</a> — 集控服务器功能总览</li><li><a href="/faq.html">常见问题</a> — 常见问题解答</li></ul>',26)])])}const b=a(i,[["render",l]]);export{g as __pageData,b as default};
